    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(uint salt) public payable {
        salt; // no precondition needed; rule must hold for any input
        uint balanceBefore = address(c).balance;
        uint firstRead = c.pastBlockTime(); if (__ESBMC_reverted()) return;
        uint secondRead = c.pastBlockTime(); if (__ESBMC_reverted()) return;
        uint balanceAfter = address(c).balance;
        assert(firstRead == secondRead && balanceBefore == balanceAfter);
    }
}

