        c = new Roulette{value: 10 ether}();
    }

    function _run(uint256 salt) internal {
        salt;
        uint balanceBefore = address(c).balance;
        uint256 firstRead;
        try c.pastBlockTime() returns (uint256 __r) { firstRead = __r; } catch { return; }
        uint256 secondRead;
        try c.pastBlockTime() returns (uint256 __r) { secondRead = __r; } catch { return; }
        uint balanceAfter = address(c).balance;
        assertTrue(firstRead == secondRead && balanceBefore == balanceAfter);
    }

    function testFuzz_run(uint256 salt) public {
        _run(salt);
    }

